using System;using System.IO;using System.Linq;using System.Drawing;using System.Drawing.Drawing2D;using System.Collections.Generic;using System.Windows.Forms;
namespace CircuitoStudio {
public sealed class FaultTimeTraceForm:Form {
readonly Project project;readonly Circuit circuit;readonly FaultTimeBinding draft;readonly List<Action> readers=new List<Action>();readonly TextBox details=new TextBox{Dock=DockStyle.Bottom,Height=220,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical};readonly Panel plot=new Panel{Dock=DockStyle.Fill,BackColor=Color.White};readonly NumericUpDown time=new NumericUpDown{DecimalPlaces=6,Maximum=1000000,Width=110};FaultTimeBinding rendered;public bool Changed{get;private set;}
public FaultTimeTraceForm(Project p,Circuit c){if(c==null)throw new InvalidDataException("Selecione um circuito para anexar o caso documentado.");project=p;circuit=c;draft=c.FaultTimeTrace==null?new FaultTimeBinding{FrequencyHz=p.Frequency}:c.FaultTimeTrace.Copy();Text="Histórico temporal de curto importado — "+c.Id;Size=new Size(1510,960);MinimumSize=new Size(1200,800);Font=new Font("Segoe UI",10);var split=new SplitContainer{Dock=DockStyle.Fill};split.Size=new Size(1470,850);split.SplitterDistance=630;split.Panel1.Controls.Add(TypedFields.Create(draft,readers));var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=115};Add(bar,"Importar CSV / vincular",()=>{using(var d=new OpenFileDialog{Filter="Tempo/corrente CSV|*.csv"})if(d.ShowDialog(this)==DialogResult.OK)ImportDraft(d.FileName);});Add(bar,"Calcular cópia",()=>EvaluateDraft(false));Add(bar,"Salvar histórico",()=>EvaluateDraft(true));Add(bar,"CSV de amostras",()=>{if(!EvaluateDraft(false).Accepted)throw new InvalidDataException("Sem histórico aceito.");using(var d=new SaveFileDialog{Filter="Amostras CSV (metadados ficam no projeto)|*.csv"})if(d.ShowDialog(this)==DialogResult.OK)FaultTimeTrace.ExportSamples(draft,d.FileName);});Add(bar,"Remover",()=>{circuit.FaultTimeTrace=null;rendered=null;Changed=true;plot.Invalidate();details.Text="Histórico removido.";});bar.Controls.Add(new Label{Text="Consultar tempo (s)",AutoSize=true,Padding=new Padding(0,5,0,0)});bar.Controls.Add(time);Add(bar,"Consultar",()=>{double value=Query((double)time.Value);details.Text+="\r\nI("+time.Value+"s)="+value.ToString("G10")+" A — "+draft.Kind+"; sem extrapolação.";});plot.Paint+=Draw;plot.Resize+=(s,e)=>plot.Invalidate();split.Panel2.Controls.Add(plot);split.Panel2.Controls.Add(details);split.Panel2.Controls.Add(bar);Controls.Add(split);details.Text="Declare caso físico/local/fase, documento/hash, equipamento, condições e aquisição. CSV TimeSeconds;CurrentA em s/A; tempos crescentes. Amostra instantânea assinada inclui o sinal; envelope AC RMS não é onda instantânea, pico assimétrico ou componenteDC. Importar vincula à fonte/rede atuais e guarda cópia; salvar grava no projeto. CSV de amostras não contém metadados: preserve também o projeto. Sem extrapolação ou aprovação de tempo de proteção. Curva de terminais de máquina não é propagada automaticamente por cabo.";}
void Add(Control parent,string text,Action action){var b=new Button{Text=text,AutoSize=true};b.Click+=(s,e)=>{try{action();}catch(Exception ex){details.Text="Operação recusada: "+ex.Message;}};parent.Controls.Add(b);}
void Read(){foreach(var reader in readers)reader();draft.Validate();}
public void ImportDraft(string path){Read();var imported=FaultTimeTrace.Import(project,circuit,draft,path);draft.Samples=imported.Samples;draft.ElectricalContext=imported.ElectricalContext;draft.SamplesSha256=imported.SamplesSha256;EvaluateDraft(false);}
public FaultTimeResult EvaluateDraft(bool commit){Read();var result=FaultTimeTrace.Evaluate(project,circuit,draft);if(commit){circuit.FaultTimeTrace=draft.Copy();Changed=true;}rendered=result.Accepted?draft.Copy():null;details.Text=result.Status+"\r\n"+result.Detail+"\r\nPico instantâneo observado(A): "+(result.ObservedInstantaneousPeakA.HasValue?result.ObservedInstantaneousPeakA.Value.ToString("G10"):"não fornecido")+"; AC RMS mín/máx(A): "+(result.MinimumSymmetricRmsA.HasValue?result.MinimumSymmetricRmsA+" / "+result.MaximumSymmetricRmsA:"não deduzido")+"; FPcc declarado: "+(result.DeclaredFaultPowerFactor.HasValue?result.DeclaredFaultPowerFactor.Value.ToString():"desconhecido");plot.Invalidate();return result;}
public double Query(double seconds){EvaluateDraft(false);return FaultTimeTrace.At(project,circuit,draft,seconds);}
void Draw(object sender,PaintEventArgs e){if(rendered==null||plot.Width<150||plot.Height<150)return;var samples=rendered.Samples;bool log=rendered.Interpolation==TraceInterpolation.LogLog;Func<double,double> axis=x=>log?Math.Log10(x):x;double xmin=axis(samples.First().TimeSeconds),xmax=axis(samples.Last().TimeSeconds),ymin=samples.Min(x=>axis(x.CurrentA)),ymax=samples.Max(x=>axis(x.CurrentA));if(ymax==ymin){ymax+=1;ymin-=1;}var rect=new RectangleF(90,65,plot.Width-120,plot.Height-120);e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;e.Graphics.DrawRectangle(Pens.LightGray,rect.X,rect.Y,rect.Width,rect.Height);e.Graphics.DrawString(rendered.Kind==FaultTraceKind.SymmetricRmsEnvelope?"Envelope AC simétrico RMS (A) — sem pico instantâneo":"Corrente instantânea de uma fase (A) — pico observado",Font,Brushes.Black,12,10);e.Graphics.DrawString(log?"Eixos logarítmicos; interpolação log-log":"Eixos lineares; interpolação linear",Font,Brushes.DimGray,12,33);Func<double,string> label=x=>(log?Math.Pow(10,x):x).ToString("G5");e.Graphics.DrawString(label(ymax),Font,Brushes.DimGray,0,rect.Top);e.Graphics.DrawString(label(ymin),Font,Brushes.DimGray,0,rect.Bottom-20);e.Graphics.DrawString(label(xmin)+" s",Font,Brushes.DimGray,rect.Left,rect.Bottom+8);e.Graphics.DrawString(label(xmax)+" s",Font,Brushes.DimGray,rect.Right-100,rect.Bottom+8);var points=samples.Select(x=>new PointF(rect.Left+(float)((axis(x.TimeSeconds)-xmin)/(xmax-xmin))*rect.Width,rect.Bottom-(float)((axis(x.CurrentA)-ymin)/(ymax-ymin))*rect.Height)).ToArray();using(var pen=new Pen(Color.RoyalBlue,1.7f))e.Graphics.DrawLines(pen,points);foreach(var point in points)e.Graphics.FillEllipse(Brushes.RoyalBlue,point.X-2,point.Y-2,4,4);}
}
partial class Studio{void ConfigureFaultTimeTrace(){if(circuit==null)throw new InvalidDataException("Selecione um circuito.");using(var f=new FaultTimeTraceForm(project,circuit)){f.ShowDialog(this);if(f.Changed)Change();}}}
}
